#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { parse, ParseError, Table, Aot, Arr } from './parser.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const cmp = (a, b) => {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const sorted = (t) => [...t.map.entries()].sort((a, b) => cmp(a[0], b[0]))
const kids = (n) => n instanceof Table ? sorted(n) : (n instanceof Aot || n instanceof Arr) ? n.items.map((x, i) => [i, x]) : []

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  if (n instanceof Table) {
    if (!n.map.size) return '{}'
    return '{\n' + sorted(n).map(([k, v]) => pad + JSON.stringify(k) + ': ' + toJson(v, ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n instanceof Aot || n instanceof Arr) {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + toJson(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}
const typeOf = (n) => n instanceof Table ? 'table' : (n instanceof Aot || n instanceof Arr) ? 'array' : n.t

function keys(n, path, out) {
  for (const [k, v] of kids(n)) {
    const p = typeof k === 'number' ? `${path}[${k}]` : path === '' ? k : `${path}.${k}`
    out.push(`${p} ${typeOf(v)}`)
    keys(v, p, out)
  }
}

let root
